  "check_code": "import sqlite3
from pathlib import Path


TARGET_CONFIRMATION = "CNF-CF-006"
TARGET_FINDING = "FND-CF-CONTRIB-001"
TARGET_TEAM = "TEAM-CUSTOMER-SUPPORT"


def _db(ws):
    ws = Path(ws)
    candidates = [
        ws / "system" / "postmortem_knowledge_base" / "state.db",
        ws.parent / "system" / "postmortem_knowledge_base" / "state.db",
    ]
    return next((path for path in candidates if path.exists()), candidates[0])


def _row_tuple(row):
    return tuple(row) if row is not None else None


def check_confirmation_updated(ws):
    path = _db(ws)
    if not path.exists():
        return {"score": 0, "detail": "postmortem_knowledge_base state.db 不存在"}
    with sqlite3.connect(path) as con:
        con.row_factory = sqlite3.Row
        row = con.execute(
            "SELECT confirmation_id, finding_id, team_id, meeting_date, confirmation_status, dissent_text, confirmed_by "
            "FROM meeting_confirmation WHERE confirmation_id = ?",
            (TARGET_CONFIRMATION,),
        ).fetchone()
        count = con.execute(
            "SELECT COUNT(*) FROM meeting_confirmation WHERE finding_id = ? AND team_id = ?",
            (TARGET_FINDING, TARGET_TEAM),
        ).fetchone()[0]
    if row is None:
        return {"score": 0, "detail": "目标确认记录不存在"}
    expected = (TARGET_CONFIRMATION, TARGET_FINDING, TARGET_TEAM, "2022-07-12", "confirmed", None)
    actual = _row_tuple(row)[:6]
    if actual != expected:
        return {"score": 0, "detail": f"目标确认后态不符: {actual!r}"}
    if not (row["confirmed_by"] and str(row["confirmed_by"]).strip()):
        return {"score": 0, "detail": "confirmed_by 为空"}
    if count != 1:
        return {"score": 0, "detail": f"同一发现/团队确认记录数为 {count}，应为 1"}
    return {"score": 1, "detail": "目标确认已正式确认、登记确认人且保持唯一"}


def check_unmodified_records(ws):
    current = _db(ws)
    baseline = current.with_name("state.db.pinned_backup")
    if not current.exists() or not baseline.exists():
        return {"score": 0, "detail": "缺少当前库或基线库"}
    with sqlite3.connect(current) as now, sqlite3.connect(baseline) as old:
        scoped_queries = {
            "evidence_source": "SELECT * FROM evidence_source WHERE incident_id = 'INC-CF-20220621' ORDER BY 1",
            "evidence_claim": "SELECT * FROM evidence_claim WHERE incident_id = 'INC-CF-20220621' ORDER BY 1",
            "postmortem_finding": "SELECT * FROM postmortem_finding WHERE incident_id = 'INC-CF-20220621' ORDER BY 1",
        }
        for table, query in scoped_queries.items():
            current_rows = now.execute(query).fetchall()
            baseline_rows = old.execute(query).fetchall()
            if current_rows != baseline_rows:
                return {"score": 0, "detail": f"{table} 存在非目标变更"}
        current_rows = now.execute(
            "SELECT m.* FROM meeting_confirmation m JOIN postmortem_finding f ON f.finding_id = m.finding_id "
            "WHERE f.incident_id = 'INC-CF-20220621' AND m.confirmation_id <> ? ORDER BY 1",
            (TARGET_CONFIRMATION,),
        ).fetchall()
        baseline_rows = old.execute(
            "SELECT m.* FROM meeting_confirmation m JOIN postmortem_finding f ON f.finding_id = m.finding_id "
            "WHERE f.incident_id = 'INC-CF-20220621' AND m.confirmation_id <> ? ORDER BY 1",
            (TARGET_CONFIRMATION,),
        ).fetchall()
        if current_rows != baseline_rows:
            return {"score": 0, "detail": "其他团队确认或其他确认记录被修改"}
    return {"score": 1, "detail": "证据、发现和其他确认记录均保持不变"}
